-- qr_086: which sense each Qurʾānic word uses — the thin QR binding of the 360° word-sense layer
-- (km_quran__043). The senses and arcs themselves are AL's (0125, lemma scope); this says only
-- "this occurrence means AL sense X, by arc Y". A lemma's range in the Qurʾān is the AL senses its
-- occurrences link to, each cited from the verse that holds it.
--
-- 40:2–3 carry their evidence (al-Ṭabarī, Ibn ʿĀshūr, the lexicons) from qr_word_occurrence.here_src_json,
-- which this retires along with here_sense; here_en (the word's short meaning in its āyah) stays.

-- نزل
INSERT OR IGNORE INTO qr_word_sense_link (id, word_occ_id, al_sense_id, al_arc_id, surah_no, ayah_no, word_index, ayah_key, is_contextual, is_primary, display_order, evidence_json, confidence, status)
  SELECT 'WSL:' || o.surah || ':' || o.ayah || ':' || o.word_index || ':tanzil_revelation', o.id, 'SNS:نزل:tanzil_revelation', 'ARC:نزل:tanzil', o.surah, o.ayah, o.word_index, o.surah || ':' || o.ayah, 1, 1, 1, (SELECT json_group_array(json_object('kind', CASE WHEN json_extract(value,'$.src') IN ('tabari','ibn_ashur') THEN 'tafsir' ELSE 'lexicon' END, 'slug', json_extract(value,'$.src'), 'ref', json_extract(value,'$.ref'), 'quote_ar', json_extract(value,'$.ar'), 'agreement', 'supports')) FROM json_each(COALESCE(o.here_src_json, '[]'))), 'high', 'live'
    FROM qr_word_occurrence o WHERE o.gid_lemma = 'AL:1bc35f366d52a6776e838f0c4d' AND o.surah = 40 AND o.ayah = 2;
